@pytest.mark.parametrize(
    "parts, unsplit",
    [
        (("https", None, "httpbin.org"), "https://httpbin.org"),
        (("https", "user", "httpbin.org"), "https://user@httpbin.org"),
        (
            ("https", None, "httpbin.org", 443, "/get"),
            "https://httpbin.org:443/get",
        ),
        (("HTTPS", None, "HTTPBIN.ORG"), "https://httpbin.org"),
    ],
)
def test_from_parts(parts, unsplit):
    uri = pr.ParseResult.from_parts(*parts)
    assert uri.unsplit() == unsplit

@pytest.mark.parametrize(
    "parts, unsplit",
    [
        (("https", None, "httpbin.org"), b"https://httpbin.org"),
        (("https", "user", "httpbin.org"), b"https://user@httpbin.org"),
        (
            ("https", None, "httpbin.org", 443, "/get"),
            b"https://httpbin.org:443/get",
        ),
        (("HTTPS", None, "HTTPBIN.ORG"), b"https://httpbin.org"),
    ],
)
def test_bytes_from_parts(parts, unsplit):
    uri = pr.ParseResultBytes.from_parts(*parts)
    assert uri.unsplit() == unsplit

def test_unsplit(self):
    uri = pr.ParseResultBytes.from_string(
        b"http://" + SNOWMAN + b".com/path", strict=False
    )
    idna_encoded = SNOWMAN_IDNA_HOST.encode("utf-8") + b"/path"
    assert uri.unsplit(use_idna=True) == idna_encoded

def test_normalize_percent_characters():
    expected = "%3Athis_should_be_lowercase%DF%AB%4C"
    assert expected == normalize_percent_characters(
        "%3athis_should_be_lowercase%DF%ab%4c"
    )
    assert expected == normalize_percent_characters(
        "%3Athis_should_be_lowercase%DF%AB%4C"
    )
    assert expected == normalize_percent_characters(
        "%3Athis_should_be_lowercase%DF%aB%4C"

def test_remove_dot_segments(path_fixture):
    to_normalize, expected = path_fixture
    assert expected == remove_dot_segments(to_normalize)

def test_hostname_normalization():
    assert URIReference(None, "EXAMPLE.COM", None, None, None) == URIReference(
        None, "example.com", None, None, None

@pytest.mark.parametrize(
    ["authority", "expected_authority"],
    [
        ("user%2aName@EXAMPLE.COM", "user%2AName@example.com"),
        ("[::1%eth0]", "[::1%25eth0]"),
    ],
)
def test_authority_normalization(authority, expected_authority):
    uri = URIReference(None, authority, None, None, None).normalize()
    assert uri.authority == expected_authority

def test_fragment_normalization():
    uri = URIReference(None, "example.com", None, None, "fiz%DF").normalize()
    assert uri.fragment == "fiz%DF"

@requires_idna
@iri_to_uri
def test_encode_iri(iri, uri):
    assert rfc3986.iri_reference(iri).encode().unsplit() == uri

@iri_to_uri
def test_iri_equality(iri, uri):
    assert rfc3986.iri_reference(iri) == iri

